java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
java.awt.image.BufferedImage img;

try (java.io.InputStream is = new java.io.FileInputStream(grid_png);
     java.io.OutputStream os = baos) {

    net.coobird.thumbnailator.ThumbnailParameter param = new net.coobird.thumbnailator.ThumbnailParameter(
            new java.awt.Dimension(50, 50),
            null,
            true,
            "png",
            net.coobird.thumbnailator.ThumbnailParameter.DEFAULT_FORMAT_TYPE,
            net.coobird.thumbnailator.ThumbnailParameter.DEFAULT_QUALITY,
            java.awt.image.BufferedImage.TYPE_INT_ARGB,
            null,
            net.coobird.thumbnailator.resizers.Resizers.PROGRESSIVE,
            true,
            true
    );

    net.coobird.thumbnailator.tasks.StreamThumbnailTask task = new net.coobird.thumbnailator.tasks.StreamThumbnailTask(param, is, os);

    // The task reads the source image from the InputStream
    img = task.read();
    assert img != null : "Task should read a valid image from the InputStream";

    // The task writes the provided image to the OutputStream using the configured parameters
    task.write(img);
}

byte[] outBytes = baos.toByteArray();
assert outBytes.length > 0 : "Task should have written data to the output stream";

try (java.io.InputStream in = new java.io.ByteArrayInputStream(outBytes)) {
    java.awt.image.BufferedImage outImg = javax.imageio.ImageIO.read(in);
    assert outImg != null : "Output data should be a valid readable image";

    // Since we wrote the original image back without resizing it through the Thumbnailator pipeline,
    // the dimensions should match the original image exactly.
    assert outImg.getWidth() == img.getWidth() : "Output width should match the written image width";
    assert outImg.getHeight() == img.getHeight() : "Output height should match the written image height";

    System.out.println("__CHECK__ StreamThumbnailTask " + outBytes.length + " bytes, " + outImg.getWidth() + "x" + outImg.getHeight());
}

